21	namespace ascend_kernel {
22	
23	constexpr int32_t GATHER_MODE_LAST_DIM = 0;
24	constexpr int32_t GATHER_MODE_TRANSPOSE = 1;
25	constexpr int32_t GATHER_MODE_SCALAR = 2;
26	
27	inline int32_t CeilDivI32(int32_t a, int32_t b)
28	{
29	    if (b == 0) { return 0; }
30	    return (a + b - 1) / b;
31	}
32	
33	inline int32_t ChooseBlockM(int32_t m)
34	{
35	    int32_t blockM = 32;
36	    if (m < 32) blockM = 16;
37	    if (m < 16) blockM = 8;
38	    if (m < 8) blockM = 4;
39	    if (m < 4) blockM = 2;
40	    if (m < 2) blockM = 1;
41	    return blockM;
42	}
