83	                    totalRowsLval, nLval, kLval, dtypeSizeLval, totalRowsLval, rowOffsetLval);
84	
85	    // ---- Output reshape ----
86	    // [batch, rows, K] -> transpose back -> index.sizes()
87	    std::vector<int64_t> transposedOutShape;
88	    for (int64_t i = 0; i < ndim; i++) {
