#include "torch_kernel_helper.h"
#include "aclrtlaunch_gather.h"
#include <torch/extension.h>
#include <algorithm>

namespace ascend_kernel {

constexpr int64_t MAX_CORES = 40;

at::Tensor gather(const at::Tensor& self, int64_t dim, const at::Tensor& index, bool sparse_grad) {
    // ---- Input validation ----
    TORCH_CHECK(self.device().type() == at::DeviceType::PrivateUse1,
                "gather: self must be on NPU device");
    TORCH_CHECK(index.device().type() == at::DeviceType::PrivateUse1,
                "gather: index must be on NPU device");

    int64_t ndim = self.dim();
    if (dim < 0) dim += ndim;

    TORCH_CHECK(dim >= 0 && dim < ndim,
                "gather: dim out of range, got dim=", dim);
    TORCH_CHECK(index.dim() == ndim,
                "gather: index must have same ndim as self");

    TORCH_CHECK(self.scalar_type() == at::kFloat ||
                self.scalar_type() == at::kHalf ||
                self.scalar_type() == at::kBFloat16,
                "gather: only float32, float16 and bfloat16 are supported");

    // ---- Contiguous ----
    at::Tensor selfContiguous = self.contiguous();
    at::Tensor indexContiguous = index.contiguous();

    // ---- Dimension params ----
    int64_t N = selfContiguous.size(dim);   // source dim size
    int64_t K = indexContiguous.size(dim);  // index dim size
    int64_t dtypeSize = selfContiguous.element_size();

    // ---- Index to int32 ----
    auto indexInt32 = indexContiguous.to(at::kInt);

    // ---- 3D dimension unification ----
    // transpose(dim, -1) moves dim to last dim, then reshape to [batch, rows, N/K]
    // For gather: self and index may have different shapes in non-dim dimensions
    // We compute batch/rows separately for self and index

    // Self dimensions
    int64_t selfBatch = 1;
    for (int64_t i = 0; i < dim; i++) selfBatch *= selfContiguous.size(i);
    int64_t selfRows = 1;
    for (int64_t i = dim + 1; i < ndim; i++) selfRows *= selfContiguous.size(i);

    // Index dimensions (output shape = index shape)
    int64_t indexBatch = 1;
    for (int64_t i = 0; i < dim; i++) indexBatch *= indexContiguous.size(i);
    int64_t indexRows = 1;
    for (int64_t i = dim + 1; i < ndim; i++) indexRows *= indexContiguous.size(i);

    // Self: transpose(dim, -1) -> [selfBatch, selfRows, N]
    auto selfFlat = selfContiguous.transpose(dim, -1).contiguous()
                        .reshape({selfBatch, selfRows, N});
    // Index: transpose(dim, -1) -> [indexBatch, indexRows, K]
    auto indexFlat = indexInt32.transpose(dim, -1).contiguous()
                        .reshape({indexBatch, indexRows, K});

    // Output: [indexBatch, indexRows, K]
    auto outputFlat = at::empty({indexBatch, indexRows, K},
        selfContiguous.options().dtype(
            selfContiguous.scalar_type() == at::kBFloat16
                ? at::kBFloat16 : selfContiguous.scalar_type()));

    // ---- Batch launch ----
    int64_t totalRows = indexBatch * indexRows;
    int64_t rowOffset = 0;
    int64_t blockDimInt = std::min(totalRows, MAX_CORES);
    if (blockDimInt < 1) blockDimInt = 1;
    uint32_t blockDim = static_cast<uint32_t>(blockDimInt);

    // EXEC_KERNEL_CMD: all params must be lvalues
    int64_t totalRowsLval = totalRows;
    int64_t nLval = N;
    int64_t kLval = K;
    int64_t dtypeSizeLval = dtypeSize;
    int64_t rowOffsetLval = rowOffset;

    EXEC_KERNEL_CMD(gather, blockDim, selfFlat, indexFlat, outputFlat,
                    totalRowsLval, nLval, kLval, dtypeSizeLval, totalRowsLval, rowOffsetLval);

    // ---- Output reshape ----
    // outputFlat is [indexBatch, indexRows, K] after transpose(dim, -1) and reshape
    // Need to reshape back to index's original shape
    // transpose(-1, dim) moves K back to dim position
    auto outputTransposed = outputFlat.reshape(indexContiguous.transpose(dim, -1).sizes())
                               .transpose(ndim - 1, dim).contiguous();

    return outputTransposed.reshape(index.sizes());
}

}  // namespace ascend_kernel
