19	template<typename T>
20	class GatherKernel {
21	public:
22	    __aicore__ inline GatherKernel() {}
23	
24	    __aicore__ inline void Init(GM_ADDR input, GM_ADDR index, GM_ADDR output,
25	                                 int64_t inputRows, int64_t srcDimSize,
26	                                 int64_t indexSize, int64_t totalRows,
