33	    __aicore__ inline void ProcessElementPath(int64_t row);
34	
35	    __aicore__ inline void LoadIndexForRow(int64_t row, LocalTensor<int32_t> &indexLocal)
36	    {
37	        DataCopyExtParams params;
38	        params.blockCount = 1;
39	        params.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(int32_t));
40	        params.srcStride = 0;
41	        params.dstStride = 0;
42	        DataCopyPadExtParams<int32_t> padParams;
43	        padParams.isPad = false;
44	        DataCopyPad(indexLocal, indexGm_[row * indexSize_], params, padParams);
45	        PipeBarrier<PIPE_ALL>();
46	    }
47	
48	    __aicore__ inline void WriteOutputForRow(int64_t row, LocalTensor<T> &outputLocal)
49	    {
50	        DataCopyExtParams params;
51	        params.blockCount = 1;
52	        params.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(T));
53	        params.srcStride = 0;
54	        params.dstStride = 0;
55	        DataCopyPad(outputGm_[row * indexSize_], outputLocal, params);
56	        PipeBarrier<PIPE_ALL>();
57	    }
