85	    int64_t inputRowBytes_ = 0;
86	    int64_t indexRowBytes_ = 0;
87	    int64_t outputRowBytes_ = 0;
88	    int64_t maxRowsPerBatch_ = 1;
89	    int8_t path_ = 0;
90	};
91	
92	template<typename T>
93	__aicore__ inline void GatherKernel<T>::Init(GM_ADDR input, GM_ADDR index, GM_ADDR output,
94	                                               int64_t inputRows, int64_t srcDimSize,
95	                                               int64_t indexSize, int64_t totalRows,
96	                                               int64_t rowOffset) {
97	    inputRows_ = inputRows;
98	    srcDimSize_ = srcDimSize;
99	    indexSize_ = indexSize;
100	    totalRows_ = totalRows;
101	    rowOffset_ = rowOffset;
102	
103	    inputGm_.SetGlobalBuffer((__gm__ T*)input, inputRows * srcDimSize);
104	    indexGm_.SetGlobalBuffer((__gm__ int32_t*)index);
105	    outputGm_.SetGlobalBuffer((__gm__ T*)output);
106	
107	    // 32-byte aligned row bytes
108	    inputRowBytes_  = ((srcDimSize * sizeof(T) + 31) / 32) * 32;
109	    indexRowBytes_  = ((indexSize * sizeof(int32_t) + 31) / 32) * 32;
110	    outputRowBytes_ = ((indexSize * sizeof(T) + 31) / 32) * 32;
111	
112	    int64_t perRowUB = inputRowBytes_ + indexRowBytes_ + outputRowBytes_;
113	
114	    if (perRowUB <= UB_CAPACITY && srcDimSize * sizeof(T) <= MAX_GATHER_SRC_BYTES
115	        && srcDimSize * sizeof(T) >= 32) {
116	        // Path 0: GatherPath - hardware Gather instruction
117	        path_ = 0;
118	        maxRowsPerBatch_ = UB_CAPACITY / perRowUB;
119	        if (maxRowsPerBatch_ < 1) maxRowsPerBatch_ = 1;
120	        pipe_.InitBuffer(inputBuf_,  maxRowsPerBatch_ * inputRowBytes_);
121	        pipe_.InitBuffer(indexBuf_,  maxRowsPerBatch_ * indexRowBytes_);
122	        pipe_.InitBuffer(outputBuf_, maxRowsPerBatch_ * outputRowBytes_);
123	    } else if (perRowUB <= UB_CAPACITY) {
124	        // Path 1: UBPath - scalar UB access
125	        path_ = 1;
126	        pipe_.InitBuffer(ubInputBuf_,  inputRowBytes_);
127	        pipe_.InitBuffer(ubIndexBuf_,  indexRowBytes_);
128	        pipe_.InitBuffer(ubOutputBuf_, outputRowBytes_);
129	    } else {
130	        // Path 2: ElementPath - direct GM element access
131	        path_ = 2;
132	        pipe_.InitBuffer(indexBufElem_,  indexRowBytes_);
133	        pipe_.InitBuffer(outputBufElem_, outputRowBytes_);
134	    }
135	}
136	
137	template<typename T>
138	__aicore__ inline void GatherKernel<T>::ProcessGatherPath(int64_t startRow, int64_t numRows) {
139	    LocalTensor<T> inputLocal = inputBuf_.Get<T>();
140	    LocalTensor<int32_t> indexLocal = indexBuf_.Get<int32_t>();
141	    LocalTensor<T> outputLocal = outputBuf_.Get<T>();
142	
143	    // 1. Load input rows -> UB
144	    DataCopyExtParams inputCopyParams;
145	    inputCopyParams.blockCount = 1;
146	    inputCopyParams.blockLen = static_cast<uint32_t>(srcDimSize_ * sizeof(T));
147	    inputCopyParams.srcStride = 0;
148	    inputCopyParams.dstStride = 0;
149	    DataCopyPadExtParams<T> inputPadParams;
150	    inputPadParams.isPad = false;
151	    for (int64_t r = 0; r < numRows; r++) {
152	        DataCopyPad(inputLocal[r * (inputRowBytes_ / sizeof(T))],
153	                    inputGm_[(startRow + r) * srcDimSize_], inputCopyParams, inputPadParams);
154	    }
155	    PipeBarrier<PIPE_ALL>();
156	
157	    // 2. Load index rows -> UB (each row has independent index)
158	    DataCopyExtParams indexCopyParams;
159	    indexCopyParams.blockCount = 1;
160	    indexCopyParams.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(int32_t));
161	    indexCopyParams.srcStride = 0;
162	    indexCopyParams.dstStride = 0;
163	    DataCopyPadExtParams<int32_t> indexPadParams;
164	    indexPadParams.isPad = false;
165	    for (int64_t r = 0; r < numRows; r++) {
166	        DataCopyPad(indexLocal[r * (indexRowBytes_ / sizeof(int32_t))],
167	                    indexGm_[(startRow + r) * indexSize_], indexCopyParams, indexPadParams);
168	    }
169	    PipeBarrier<PIPE_ALL>();
170	
171	    // 3. Muls: element index -> byte offset (critical step!)
172	    for (int64_t r = 0; r < numRows; r++) {
173	        int64_t off = r * (indexRowBytes_ / sizeof(int32_t));
174	        Muls(indexLocal[off], indexLocal[off], (int32_t)sizeof(T), indexSize_);
175	    }
176	    PipeBarrier<PIPE_ALL>();
177	
178	    // 4. ReinterpretCast + Gather
179	    LocalTensor<uint32_t> indexUintLocal = indexLocal.ReinterpretCast<uint32_t>();
180	    for (int64_t r = 0; r < numRows; r++) {
181	        int64_t inOff  = r * (inputRowBytes_ / sizeof(T));
182	        int64_t idxOff = r * (indexRowBytes_ / sizeof(uint32_t));
183	        int64_t outOff = r * (outputRowBytes_ / sizeof(T));
184	        Gather(outputLocal[outOff], inputLocal[inOff], indexUintLocal[idxOff],
185	               (uint32_t)0, static_cast<uint32_t>(indexSize_));
186	        PipeBarrier<PIPE_ALL>();
187	    }
188	
189	    // 5. Write back output UB -> GM
190	    DataCopyExtParams outputCopyParams;
191	    outputCopyParams.blockCount = 1;
192	    outputCopyParams.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(T));
193	    outputCopyParams.srcStride = 0;
194	    outputCopyParams.dstStride = 0;
195	    for (int64_t r = 0; r < numRows; r++) {
196	        DataCopyPad(outputGm_[(startRow + r) * indexSize_],
197	                    outputLocal[r * (outputRowBytes_ / sizeof(T))], outputCopyParams);
198	    }
199	    PipeBarrier<PIPE_ALL>();
200	}
201	
202	template<typename T>
203	__aicore__ inline void GatherKernel<T>::ProcessUBPath(int64_t row) {
204	    LocalTensor<T> inputLocal = ubInputBuf_.Get<T>();
205	    LocalTensor<int32_t> indexLocal = ubIndexBuf_.Get<int32_t>();
206	    LocalTensor<T> outputLocal = ubOutputBuf_.Get<T>();
207	
208	    // Load input row
209	    DataCopyExtParams inputCopyParams;
210	    inputCopyParams.blockCount = 1;
211	    inputCopyParams.blockLen = static_cast<uint32_t>(srcDimSize_ * sizeof(T));
212	    inputCopyParams.srcStride = 0;
213	    inputCopyParams.dstStride = 0;
214	    DataCopyPadExtParams<T> inputPadParams;
215	    inputPadParams.isPad = false;
216	    DataCopyPad(inputLocal, inputGm_[row * srcDimSize_], inputCopyParams, inputPadParams);
217	    PipeBarrier<PIPE_ALL>();
218	
219	    // Load this row's index (each row independent)
220	    LoadIndexForRow(row, indexLocal);
221	
222	    // Scalar index gather
223	    for (int64_t j = 0; j < indexSize_; j++) {
224	        int32_t idx = indexLocal.GetValue(j);
225	        T val = inputLocal.GetValue(idx);
226	        outputLocal.SetValue(j, val);
227	    }
228	    PipeBarrier<PIPE_ALL>();
229	
230	    // Write back output
231	    WriteOutputForRow(row, outputLocal);
232	}
233	
234	template<typename T>
235	__aicore__ inline void GatherKernel<T>::ProcessElementPath(int64_t row) {
236	    LocalTensor<int32_t> indexLocal = indexBufElem_.Get<int32_t>();
237	    LocalTensor<T> outputLocal = outputBufElem_.Get<T>();
238	
239	    // Load this row's index
240	    LoadIndexForRow(row, indexLocal);
241	
242	    // Direct GM element access
243	    for (int64_t j = 0; j < indexSize_; j++) {
244	        int32_t idx = indexLocal.GetValue(j);
245	        T val = inputGm_.GetValue(row * srcDimSize_ + idx);
246	        outputLocal.SetValue(j, val);
247	    }
248	    PipeBarrier<PIPE_ALL>();
249	
250	    // Write back output
251	    WriteOutputForRow(row, outputLocal);
252	}
253	
254	template<typename T>
255	__aicore__ inline void GatherKernel<T>::Process() {
256	    int64_t blockIdx_ = GetBlockIdx();
257	
258	    if (path_ == 0) {
259	        // GatherPath: continuous block assignment + multi-row batch processing
260	        int64_t blockDim = (totalRows_ < MAX_CORES) ? totalRows_ : MAX_CORES;
261	        int64_t base = totalRows_ / blockDim;
262	        int64_t remainder = totalRows_ % blockDim;
263	        int64_t myStart, myRows;
264	        if (blockIdx_ < remainder) {
265	            myStart = rowOffset_ + blockIdx_ * (base + 1);
266	            myRows = base + 1;
267	        } else {
268	            myStart = rowOffset_ + remainder * (base + 1) + (blockIdx_ - remainder) * base;
269	            myRows = base;
270	        }
271	
272	        for (int64_t r = myStart; r < myStart + myRows; r += maxRowsPerBatch_) {
273	            int64_t numRows = myStart + myRows - r;
274	            if (numRows > maxRowsPerBatch_) numRows = maxRowsPerBatch_;
275	            ProcessGatherPath(r, numRows);
276	        }
277	    } else {
278	        // UBPath / ElementPath: interleaved row assignment
279	        int64_t startRow = rowOffset_ + blockIdx_;
280	        for (int64_t r = startRow; r < rowOffset_ + totalRows_; r += MAX_CORES) {
281	            if (r >= inputRows_) break;
282	            if (path_ == 1) {
283	                ProcessUBPath(r);
284	            } else {
285	                ProcessElementPath(r);
286	            }
287	        }
288	    }
289	}
290	
291	extern "C" __global__ __aicore__ void gather(GM_ADDR input, GM_ADDR index, GM_ADDR output,
292	                                              int64_t inputRows, int64_t srcDimSize,
293	                                              int64_t indexSize, int64_t dtypeSize,
294	                                              int64_t totalRows, int64_t rowOffset) {
295	    if (dtypeSize == 4) {
296	        GatherKernel<float> op;
297	        op.Init(input, index, output, inputRows, srcDimSize, indexSize, totalRows, rowOffset);
298	        op.Process();
299	    } else if (dtypeSize == 2) {
300	        // fp16 and bf16 are both 2 bytes, use half path for data movement
301	        GatherKernel<half> op;
302	        op.Init(input, index, output, inputRows, srcDimSize, indexSize, totalRows, rowOffset);
303	        op.Process();
304	    }
