#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t UB_CAPACITY = 192 * 1024;
constexpr int64_t MAX_GATHER_SRC_BYTES = 32 * 1024;
constexpr int64_t MAX_CORES = 40;

template<typename T>
class GatherKernel {
public:
    __aicore__ inline GatherKernel() {}

    __aicore__ inline void Init(GM_ADDR input, GM_ADDR index, GM_ADDR output,
                                 int64_t srcDimSize, int64_t indexSize,
                                 int64_t selfRowsPerBatch, int64_t indexRowsPerBatch,
                                 int64_t totalRows, int64_t rowOffset);
    __aicore__ inline void Process();

private:
    __aicore__ inline void ProcessGatherPath(int64_t startRow, int64_t numRows);
    __aicore__ inline void ProcessUBPath(int64_t row);
    __aicore__ inline void ProcessElementPath(int64_t row);

    __aicore__ inline int64_t GetSelfRowIndex(int64_t indexRow) {
        // indexRow = b * indexRowsPerBatch_ + r
        // selfRow = b * selfRowsPerBatch_ + r
        int64_t b = indexRow / indexRowsPerBatch_;
        int64_t r = indexRow % indexRowsPerBatch_;
        return b * selfRowsPerBatch_ + r;
    }

    __aicore__ inline void LoadIndexForRow(int64_t row, LocalTensor<int32_t> &indexLocal)
    {
        DataCopyExtParams params;
        params.blockCount = 1;
        params.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(int32_t));
        params.srcStride = 0;
        params.dstStride = 0;
        DataCopyPadExtParams<int32_t> padParams;
        padParams.isPad = false;
        DataCopyPad(indexLocal, indexGm_[row * indexSize_], params, padParams);
        PipeBarrier<PIPE_ALL>();
    }

    __aicore__ inline void WriteOutputForRow(int64_t row, LocalTensor<T> &outputLocal)
    {
        DataCopyExtParams params;
        params.blockCount = 1;
        params.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(T));
        params.srcStride = 0;
        params.dstStride = 0;
        DataCopyPad(outputGm_[row * indexSize_], outputLocal, params);
        PipeBarrier<PIPE_ALL>();
    }

private:
    TPipe pipe_;

    // GatherPath: multi-row batch buffers
    TBuf<TPosition::VECIN> inputBuf_;
    TBuf<TPosition::VECIN> indexBuf_;
    TBuf<TPosition::VECOUT> outputBuf_;

    // UBPath: single-row buffers
    TBuf<TPosition::VECIN> ubInputBuf_;
    TBuf<TPosition::VECIN> ubIndexBuf_;
    TBuf<TPosition::VECOUT> ubOutputBuf_;

    // ElementPath: only index + output
    TBuf<TPosition::VECIN> indexBufElem_;
    TBuf<TPosition::VECOUT> outputBufElem_;

    GlobalTensor<T> inputGm_;
    GlobalTensor<int32_t> indexGm_;
    GlobalTensor<T> outputGm_;

    int64_t srcDimSize_ = 0;
    int64_t indexSize_ = 0;
    int64_t selfRowsPerBatch_ = 0;
    int64_t indexRowsPerBatch_ = 0;
    int64_t totalRows_ = 0;
    int64_t rowOffset_ = 0;
    int64_t inputRowBytes_ = 0;
    int64_t indexRowBytes_ = 0;
    int64_t outputRowBytes_ = 0;
    int64_t maxRowsPerBatch_ = 1;
    int8_t path_ = 0;
};

template<typename T>
__aicore__ inline void GatherKernel<T>::Init(GM_ADDR input, GM_ADDR index, GM_ADDR output,
                                               int64_t srcDimSize, int64_t indexSize,
                                               int64_t selfRowsPerBatch, int64_t indexRowsPerBatch,
                                               int64_t totalRows, int64_t rowOffset) {
    srcDimSize_ = srcDimSize;
    indexSize_ = indexSize;
    selfRowsPerBatch_ = selfRowsPerBatch;
    indexRowsPerBatch_ = indexRowsPerBatch;
    totalRows_ = totalRows;
    rowOffset_ = rowOffset;

    inputGm_.SetGlobalBuffer((__gm__ T*)input);
    indexGm_.SetGlobalBuffer((__gm__ int32_t*)index);
    outputGm_.SetGlobalBuffer((__gm__ T*)output);

    // 32-byte aligned row bytes
    inputRowBytes_  = ((srcDimSize * sizeof(T) + 31) / 32) * 32;
    indexRowBytes_  = ((indexSize * sizeof(int32_t) + 31) / 32) * 32;
    outputRowBytes_ = ((indexSize * sizeof(T) + 31) / 32) * 32;

    int64_t perRowUB = inputRowBytes_ + indexRowBytes_ + outputRowBytes_;

    if (perRowUB <= UB_CAPACITY && srcDimSize * sizeof(T) <= MAX_GATHER_SRC_BYTES
        && srcDimSize * sizeof(T) >= 32) {
        // Path 0: GatherPath - hardware Gather instruction
        path_ = 0;
        maxRowsPerBatch_ = UB_CAPACITY / perRowUB;
        if (maxRowsPerBatch_ < 1) maxRowsPerBatch_ = 1;
        pipe_.InitBuffer(inputBuf_,  maxRowsPerBatch_ * inputRowBytes_);
        pipe_.InitBuffer(indexBuf_,  maxRowsPerBatch_ * indexRowBytes_);
        pipe_.InitBuffer(outputBuf_, maxRowsPerBatch_ * outputRowBytes_);
    } else if (perRowUB <= UB_CAPACITY) {
        // Path 1: UBPath - scalar UB access
        path_ = 1;
        pipe_.InitBuffer(ubInputBuf_,  inputRowBytes_);
        pipe_.InitBuffer(ubIndexBuf_,  indexRowBytes_);
        pipe_.InitBuffer(ubOutputBuf_, outputRowBytes_);
    } else {
        // Path 2: ElementPath - direct GM element access
        path_ = 2;
        pipe_.InitBuffer(indexBufElem_,  indexRowBytes_);
        pipe_.InitBuffer(outputBufElem_, outputRowBytes_);
    }
}

template<typename T>
__aicore__ inline void GatherKernel<T>::ProcessGatherPath(int64_t startRow, int64_t numRows) {
    LocalTensor<T> inputLocal = inputBuf_.Get<T>();
    LocalTensor<int32_t> indexLocal = indexBuf_.Get<int32_t>();
    LocalTensor<T> outputLocal = outputBuf_.Get<T>();

    // 1. Load input rows -> UB (from self, using self row index)
    DataCopyExtParams inputCopyParams;
    inputCopyParams.blockCount = 1;
    inputCopyParams.blockLen = static_cast<uint32_t>(srcDimSize_ * sizeof(T));
    inputCopyParams.srcStride = 0;
    inputCopyParams.dstStride = 0;
    DataCopyPadExtParams<T> inputPadParams;
    inputPadParams.isPad = false;
    for (int64_t r = 0; r < numRows; r++) {
        int64_t selfRow = GetSelfRowIndex(startRow + r);
        DataCopyPad(inputLocal[r * (inputRowBytes_ / sizeof(T))],
                    inputGm_[selfRow * srcDimSize_], inputCopyParams, inputPadParams);
    }
    PipeBarrier<PIPE_ALL>();

    // 2. Load index rows -> UB (from index, using index row index)
    DataCopyExtParams indexCopyParams;
    indexCopyParams.blockCount = 1;
    indexCopyParams.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(int32_t));
    indexCopyParams.srcStride = 0;
    indexCopyParams.dstStride = 0;
    DataCopyPadExtParams<int32_t> indexPadParams;
    indexPadParams.isPad = false;
    for (int64_t r = 0; r < numRows; r++) {
        DataCopyPad(indexLocal[r * (indexRowBytes_ / sizeof(int32_t))],
                    indexGm_[(startRow + r) * indexSize_], indexCopyParams, indexPadParams);
    }
    PipeBarrier<PIPE_ALL>();

    // 3. Muls: element index -> byte offset (critical step!)
    for (int64_t r = 0; r < numRows; r++) {
        int64_t off = r * (indexRowBytes_ / sizeof(int32_t));
        Muls(indexLocal[off], indexLocal[off], (int32_t)sizeof(T), indexSize_);
    }
    PipeBarrier<PIPE_ALL>();

    // 4. ReinterpretCast + Gather
    LocalTensor<uint32_t> indexUintLocal = indexLocal.ReinterpretCast<uint32_t>();
    for (int64_t r = 0; r < numRows; r++) {
        int64_t inOff  = r * (inputRowBytes_ / sizeof(T));
        int64_t idxOff = r * (indexRowBytes_ / sizeof(uint32_t));
        int64_t outOff = r * (outputRowBytes_ / sizeof(T));
        Gather(outputLocal[outOff], inputLocal[inOff], indexUintLocal[idxOff],
               (uint32_t)0, static_cast<uint32_t>(indexSize_));
        PipeBarrier<PIPE_ALL>();
    }

    // 5. Write back output UB -> GM
    DataCopyExtParams outputCopyParams;
    outputCopyParams.blockCount = 1;
    outputCopyParams.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(T));
    outputCopyParams.srcStride = 0;
    outputCopyParams.dstStride = 0;
    for (int64_t r = 0; r < numRows; r++) {
        DataCopyPad(outputGm_[(startRow + r) * indexSize_],
                    outputLocal[r * (outputRowBytes_ / sizeof(T))], outputCopyParams);
    }
    PipeBarrier<PIPE_ALL>();
}

template<typename T>
__aicore__ inline void GatherKernel<T>::ProcessUBPath(int64_t row) {
    LocalTensor<T> inputLocal = ubInputBuf_.Get<T>();
    LocalTensor<int32_t> indexLocal = ubIndexBuf_.Get<int32_t>();
    LocalTensor<T> outputLocal = ubOutputBuf_.Get<T>();

    // Load input row from self
    int64_t selfRow = GetSelfRowIndex(row);
    DataCopyExtParams inputCopyParams;
    inputCopyParams.blockCount = 1;
    inputCopyParams.blockLen = static_cast<uint32_t>(srcDimSize_ * sizeof(T));
    inputCopyParams.srcStride = 0;
    inputCopyParams.dstStride = 0;
    DataCopyPadExtParams<T> inputPadParams;
    inputPadParams.isPad = false;
    DataCopyPad(inputLocal, inputGm_[selfRow * srcDimSize_], inputCopyParams, inputPadParams);
    PipeBarrier<PIPE_ALL>();

    // Load this row's index from index
    LoadIndexForRow(row, indexLocal);

    // Scalar index gather
    for (int64_t j = 0; j < indexSize_; j++) {
        int32_t idx = indexLocal.GetValue(j);
        T val = inputLocal.GetValue(idx);
        outputLocal.SetValue(j, val);
    }
    PipeBarrier<PIPE_ALL>();

    // Write back output
    WriteOutputForRow(row, outputLocal);
}

template<typename T>
__aicore__ inline void GatherKernel<T>::ProcessElementPath(int64_t row) {
    LocalTensor<int32_t> indexLocal = indexBufElem_.Get<int32_t>();
    LocalTensor<T> outputLocal = outputBufElem_.Get<T>();

    // Load this row's index from index
    LoadIndexForRow(row, indexLocal);

    // Direct GM element access from self
    int64_t selfRow = GetSelfRowIndex(row);
    for (int64_t j = 0; j < indexSize_; j++) {
        int32_t idx = indexLocal.GetValue(j);
        T val = inputGm_.GetValue(selfRow * srcDimSize_ + idx);
        outputLocal.SetValue(j, val);
    }
    PipeBarrier<PIPE_ALL>();

    // Write back output
    WriteOutputForRow(row, outputLocal);
}

template<typename T>
__aicore__ inline void GatherKernel<T>::Process() {
    int64_t blockIdx_ = GetBlockIdx();

    if (path_ == 0) {
        // GatherPath: continuous block assignment + multi-row batch processing
        int64_t blockDim = (totalRows_ < MAX_CORES) ? totalRows_ : MAX_CORES;
        int64_t base = totalRows_ / blockDim;
        int64_t remainder = totalRows_ % blockDim;
        int64_t myStart, myRows;
        if (blockIdx_ < remainder) {
            myStart = rowOffset_ + blockIdx_ * (base + 1);
            myRows = base + 1;
        } else {
            myStart = rowOffset_ + remainder * (base + 1) + (blockIdx_ - remainder) * base;
            myRows = base;
        }

        for (int64_t r = myStart; r < myStart + myRows; r += maxRowsPerBatch_) {
            int64_t numRows = myStart + myRows - r;
            if (numRows > maxRowsPerBatch_) numRows = maxRowsPerBatch_;
            ProcessGatherPath(r, numRows);
        }
    } else {
        // UBPath / ElementPath: interleaved row assignment
        int64_t startRow = rowOffset_ + blockIdx_;
        for (int64_t r = startRow; r < rowOffset_ + totalRows_; r += MAX_CORES) {
            if (path_ == 1) {
                ProcessUBPath(r);
            } else {
                ProcessElementPath(r);
            }
        }
    }
}

extern "C" __global__ __aicore__ void gather(GM_ADDR input, GM_ADDR index, GM_ADDR output,
                                              int64_t srcDimSize, int64_t indexSize,
                                              int64_t selfRowsPerBatch, int64_t indexRowsPerBatch,
                                              int64_t totalRows, int64_t rowOffset) {
    if (sizeof(float) == 4) {
        GatherKernel<float> op;
        op.Init(input, index, output, srcDimSize, indexSize,
                selfRowsPerBatch, indexRowsPerBatch, totalRows, rowOffset);
        op.Process();
    } else if (sizeof(half) == 2) {
        // fp16 and bf16 are both 2 bytes, use half path for data movement
        GatherKernel<half> op;
        op.Init(input, index, output, srcDimSize, indexSize,
                selfRowsPerBatch, indexRowsPerBatch, totalRows, rowOffset);
        op.Process();
    }
}
