20	at::Tensor gather(const at::Tensor& self, int64_t dim, const at::Tensor& index, bool sparse_grad) {
21	    // ---- Input validation ----
22	    TORCH_CHECK(self.device().type() == at::DeviceType::PrivateUse1,
23	                "gather: self must be on NPU device");
24	    TORCH_CHECK(index.device().type() == at::DeviceType::PrivateUse1,
25	                "gather: index must be on NPU device");
26	
27	    int64_t ndim = self.dim();
28	    if (dim < 0) dim += ndim;
