30	    TORCH_CHECK(dim >= 0 && dim < ndim,
31	                "gather: dim out of range, got dim=", dim);
32	    TORCH_CHECK(index.dim() == ndim,
33	                "gather: index must have same ndim as self");
34	
35	    TORCH_CHECK(self.scalar_type() == at::kFloat ||
36	                self.scalar_type() == at::kHalf ||
37	                self.scalar_type() == at::kBFloat16,
38	                "gather: only float32, float16 and bfloat16 are supported");
39	
40	    // ---- Contiguous ----
41	    at::Tensor selfContiguous = self.contiguous();
42	    at::Tensor indexContiguous = index.contiguous();
43	
44	    // ---- Dimension params ----
45	    int64_t N = selfContiguous.size(dim);   // source dim size
46	    int64_t K = indexContiguous.size(dim);  // index dim size
47	    int64_t dtypeSize = selfContiguous.element_size();
48	
49	    // ---- Index to int32 ----
50	    auto indexInt32 = indexContiguous.to(at::kInt);
51	
52	    // ---- 3D dimension unification ----
53	    // transpose(dim, -1) moves dim to last dim, then reshape to [batch, rows, N/K]
54	    // For gather: self and index may have different shapes in non-dim dimensions
55	    // We compute batch/rows separately for self and index
56	
57	    // Self dimensions
58	    int64_t selfBatch = 1;
59	    for (int64_t i = 0; i < dim; i++) selfBatch *= selfContiguous.size(i);
60	    int64_t selfRows = 1;
61	    for (int64_t i = dim + 1; i < ndim; i++) selfRows *= selfContiguous.size(i);
62	
63	    // Index dimensions (output shape = index shape)
64	    int64_t indexBatch = 1;
65	    for (int64_t i = 0; i < dim; i++) indexBatch *= indexContiguous.size(i);
66	    int64_t indexRows = 1;
67	    for (int64_t i = dim + 1; i < ndim; i++) indexRows *= indexContiguous.size(i);
68	
69	    // Self: transpose(dim, -1) -> [selfBatch, selfRows, N]
70	    auto selfFlat = selfContiguous.transpose(dim, -1).contiguous()
71	                        .reshape({selfBatch, selfRows, N});
72	    // Index: transpose(dim, -1) -> [indexBatch, indexRows, K]
73	    auto indexFlat = indexInt32.transpose(dim, -1).contiguous()
74	                        .reshape({indexBatch, indexRows, K});
75	
76	    // Output: [indexBatch, indexRows, K]
77	    auto outputFlat = at::empty({indexBatch, indexRows, K},
78	        selfContiguous.options().dtype(
79	            selfContiguous.scalar_type() == at::kBFloat16
80	                ? at::kBFloat16 : selfContiguous.scalar_type()));
81	
82	    // ---- Batch launch ----
83	    int64_t totalRows = indexBatch * indexRows;
84	    int64_t rowOffset = 0;
85	    int64_t blockDimInt = std::min(totalRows, MAX_CORES);
86	    if (blockDimInt < 1) blockDimInt = 1;
87	    uint32_t blockDim = static_cast<uint32_t>(blockDimInt);
88	
89	    // EXEC_KERNEL_CMD: all params must be lvalues
90	    int64_t totalRowsLval = totalRows;
91	    int64_t nLval = N;
92	    int64_t kLval = K;
93	    int64_t dtypeSizeLval = dtypeSize;
94	    int64_t rowOffsetLval = rowOffset;
95	
96	    EXEC_KERNEL_CMD(gather, blockDim, selfFlat, indexFlat, outputFlat,
97	                    totalRowsLval, nLval, kLval, dtypeSizeLval, totalRowsLval, rowOffsetLval);
98	
99	    // ---- Output reshape ----
100	    // outputFlat is [indexBatch, indexRows, K] after transpose(dim, -1) and reshape
101	    // Need to reshape back to index's original shape
102	    // transpose(-1, dim) moves K back to dim position
103	    auto outputTransposed = outputFlat.reshape(indexContiguous.transpose(dim, -1).sizes())
104	                               .transpose(ndim - 1, dim).contiguous();
105	
106	    return outputTransposed.reshape(index.sizes());
107	}
108	
109	}  // namespace ascend_kernel
