#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t MAX_CORES = 40;

template<typename T>
class GatherKernel {
public:
    __aicore__ inline GatherKernel() {}

    __aicore__ inline void Init(GM_ADDR input, GM_ADDR index, GM_ADDR output,
                                 int64_t srcDimSize, int64_t indexSize,
                                 int64_t selfRowsPerBatch, int64_t indexRowsPerBatch,
                                 int64_t totalRows, int64_t rowOffset);
    __aicore__ inline void Process();

private:
    __aicore__ inline int64_t GetSelfRowIndex(int64_t indexRow) {
        int64_t b = indexRow / indexRowsPerBatch_;
        int64_t r = indexRow % indexRowsPerBatch_;
        return b * selfRowsPerBatch_ + r;
    }

    __aicore__ inline void ProcessRow(int64_t row);

    TPipe pipe_;

    // Queues for pipeline sync
    TQue<TPosition::VECIN, 0> inputQueue_;
    TQue<TPosition::VECIN, 0> indexQueue_;
    TQue<TPosition::VECOUT, 0> outputQueue_;

    GlobalTensor<T> inputGm_;
    GlobalTensor<int32_t> indexGm_;
    GlobalTensor<T> outputGm_;

    int64_t srcDimSize_ = 0;
    int64_t indexSize_ = 0;
    int64_t selfRowsPerBatch_ = 0;
    int64_t indexRowsPerBatch_ = 0;
    int64_t totalRows_ = 0;
    int64_t rowOffset_ = 0;
    int64_t inputRowBytes_ = 0;
    int64_t indexRowBytes_ = 0;
    int64_t outputRowBytes_ = 0;
};

template<typename T>
__aicore__ inline void GatherKernel<T>::Init(GM_ADDR input, GM_ADDR index, GM_ADDR output,
                                               int64_t srcDimSize, int64_t indexSize,
                                               int64_t selfRowsPerBatch, int64_t indexRowsPerBatch,
                                               int64_t totalRows, int64_t rowOffset) {
    srcDimSize_ = srcDimSize;
    indexSize_ = indexSize;
    selfRowsPerBatch_ = selfRowsPerBatch;
    indexRowsPerBatch_ = indexRowsPerBatch;
    totalRows_ = totalRows;
    rowOffset_ = rowOffset;

    inputGm_.SetGlobalBuffer((__gm__ T*)input);
    indexGm_.SetGlobalBuffer((__gm__ int32_t*)index);
    outputGm_.SetGlobalBuffer((__gm__ T*)output);

    // 32-byte aligned row bytes
    inputRowBytes_  = ((srcDimSize * sizeof(T) + 31) / 32) * 32;
    indexRowBytes_  = ((indexSize * sizeof(int32_t) + 31) / 32) * 32;
    outputRowBytes_ = ((indexSize * sizeof(T) + 31) / 32) * 32;

    pipe_.InitBuffer(inputQueue_, 1, inputRowBytes_);
    pipe_.InitBuffer(indexQueue_, 1, indexRowBytes_);
    pipe_.InitBuffer(outputQueue_, 1, outputRowBytes_);
}

template<typename T>
__aicore__ inline void GatherKernel<T>::ProcessRow(int64_t row) {
    // 1. Alloc tensors from queues
    LocalTensor<T> inputLocal = inputQueue_.AllocTensor<T>();
    LocalTensor<int32_t> indexLocal = indexQueue_.AllocTensor<int32_t>();
    LocalTensor<T> outputLocal = outputQueue_.AllocTensor<T>();

    // 2. Load input row from self
    int64_t selfRow = GetSelfRowIndex(row);
    uint32_t inputPadElems = (inputRowBytes_ - srcDimSize_ * sizeof(T)) / sizeof(T);
    DataCopyExtParams inputCopyParams{1, static_cast<uint32_t>(srcDimSize_ * sizeof(T)), 0, 0, 0};
    DataCopyPadExtParams<T> inputPadParams{true, 0, static_cast<uint8_t>(inputPadElems), static_cast<T>(0)};
    DataCopyPad(inputLocal, inputGm_[selfRow * srcDimSize_], inputCopyParams, inputPadParams);
    inputQueue_.EnQue(inputLocal);

    // 3. Load index row from index
    uint32_t indexPadElems = (indexRowBytes_ - indexSize_ * sizeof(int32_t)) / sizeof(int32_t);
    DataCopyExtParams indexCopyParams{1, static_cast<uint32_t>(indexSize_ * sizeof(int32_t)), 0, 0, 0};
    DataCopyPadExtParams<int32_t> indexPadParams{true, 0, static_cast<uint8_t>(indexPadElems), 0};
    DataCopyPad(indexLocal, indexGm_[row * indexSize_], indexCopyParams, indexPadParams);
    indexQueue_.EnQue(indexLocal);

    // 4. DeQue for compute
    inputQueue_.DeQue<T>(inputLocal);
    indexQueue_.DeQue<int32_t>(indexLocal);

    // 5. Scalar gather: for each index, get value from input
    for (int64_t j = 0; j < indexSize_; j++) {
        int32_t idx = indexLocal.GetValue(j);
        T val = inputLocal.GetValue(idx);
        outputLocal.SetValue(j, val);
    }

    // 6. Free input/index, EnQue output
    inputQueue_.FreeTensor(inputLocal);
    indexQueue_.FreeTensor(indexLocal);
    outputQueue_.EnQue(outputLocal);

    // 7. DeQue output and write back to GM
    outputQueue_.DeQue<T>(outputLocal);
    DataCopyExtParams outputCopyParams{1, static_cast<uint32_t>(indexSize_ * sizeof(T)), 0, 0, 0};
    DataCopyPad(outputGm_[row * indexSize_], outputLocal, outputCopyParams);
    outputQueue_.FreeTensor(outputLocal);
}

template<typename T>
__aicore__ inline void GatherKernel<T>::Process() {
    int64_t blockIdx_ = GetBlockIdx();

    // Continuous block assignment
    int64_t blockDim = (totalRows_ < MAX_CORES) ? totalRows_ : MAX_CORES;
    int64_t base = totalRows_ / blockDim;
    int64_t remainder = totalRows_ % blockDim;
    int64_t myStart, myRows;
    if (blockIdx_ < remainder) {
        myStart = rowOffset_ + blockIdx_ * (base + 1);
        myRows = base + 1;
    } else {
        myStart = rowOffset_ + remainder * (base + 1) + (blockIdx_ - remainder) * base;
        myRows = base;
    }

    for (int64_t r = myStart; r < myStart + myRows; r++) {
        ProcessRow(r);
    }
}

extern "C" __global__ __aicore__ void gather(GM_ADDR input, GM_ADDR index, GM_ADDR output,
                                              int64_t srcDimSize, int64_t indexSize,
                                              int64_t selfRowsPerBatch, int64_t indexRowsPerBatch,
                                              int64_t totalRows, int64_t rowOffset) {
    GatherKernel<float> op;
    op.Init(input, index, output, srcDimSize, indexSize,
            selfRowsPerBatch, indexRowsPerBatch, totalRows, rowOffset);
    op.Process();
}
